// Fully implemented with user validation, status transitions,
// permission checks, cache hooks, and audit integration.

import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { record } from './audit.js';
import { Cache } from './cache.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

// Shared cache instance, invalidated on every mutation.
export const taskCache = new Cache();

const VALID_TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title.trim()) {
      throw new Error('Title must not be empty');
    }
    // Validate both creator and assignee exist.
    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);

    // Invalidate cache and record audit.
    taskCache.invalidate(task.id);
    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });

    return task;
  }

  getTask(id: string): Task | null {
    // Try cache first.
    const cached = taskCache.get<Task>(id);
    if (cached !== null) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      taskCache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = VALID_TRANSITIONS[task.status];
    if (!allowed.includes(status)) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${status}`
      );
    }

    task.status = status;

    // Invalidate cache and record audit.
    taskCache.invalidate(id);
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      details: `changed to ${status}`,
      timestamp: Date.now(),
    });

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;
    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);

    // Invalidate cache and record audit.
    taskCache.invalidate(id);
    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId
    );
  }

  list(): Task[] {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
    taskCache.invalidate('__all__'); // best-effort full clear
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

