// Implemented: permission check, header row, field escaping, audit log.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsvField(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied: export requires admin role');
  }

  const tasks = taskManager.list();

  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((t) =>
    [
      escapeCsvField(t.id),
      escapeCsvField(t.title),
      escapeCsvField(t.status),
      escapeCsvField(t.assignee),
      escapeCsvField(String(t.createdAt)),
    ].join(',')
  );

  const csv = [header, ...rows].join('\n');

  record({
    action: 'export',
    userId,
    details: `exported ${tasks.length} tasks`,
    timestamp: Date.now(),
  });

  return csv;
}
